#include "assets.hpp"

#include <cstring>

#include "fonts.inc"  // kFontFile, generated by tools/make_assets.py fonts

namespace warp::ui::assets {
namespace {

// Layout of the font file (tools/make_assets.py documents it); every offset is from the start of the file.
struct FileHeader {
    char magic[4];
    uint32_t fontCount, glyphFirst, glyphCount;
};

struct FontEntry {
    uint32_t id;  // class * 10 + screen scale
    int32_t ascent, descent;
    uint32_t glyphs;
};

struct Glyph {
    int16_t xoff, yoff;
    uint16_t w, h, advance64, pad;
    uint32_t bitmap;  // 0: nothing drawn
};
static_assert(sizeof(Glyph) == 16);

constexpr int kGlyphFirst = 32, kGlyphCount = 95;
constexpr int kFontClasses = 5;

// Glyph tables by font class and scale (index 0: scale 2, 1: scale 3); null until init() accepts the file.
const Glyph* s_tables[kFontClasses][2] = {};

int scaleIndex(int scale) { return scale == 3 ? 1 : (scale == 2 ? 0 : -1); }

const Glyph* tableOf(Font font, int scale) {
    const int cls = static_cast<int>(font), index = scaleIndex(scale);
    return cls >= 0 && cls < kFontClasses && index >= 0 ? s_tables[cls][index] : nullptr;
}

const Glyph& glyph(const Glyph* table, char c) {
    int index = static_cast<unsigned char>(c) - kGlyphFirst;
    if (index < 0 || index >= kGlyphCount) { index = '?' - kGlyphFirst; }
    return table[index];
}

int width(const Glyph* table, const char* text) {
    int pen64 = 0;
    for (const char* c = text; *c != '\0'; ++c) { pen64 += glyph(table, *c).advance64; }
    return (pen64 + 32) / 64;
}

void drawGlyph(Canvas& canvas, const Glyph& g, int pen64, int y, Color color) {
    if (g.bitmap != 0) { canvas.blendMask(kFontFile + g.bitmap, g.w, g.h, (pen64 + 32) / 64 + g.xoff, y + g.yoff, color); }
}

}  // namespace

bool init() {
    constexpr size_t kSize = sizeof(kFontFile);
    FileHeader header;
    std::memcpy(&header, kFontFile, sizeof(header));
    if (std::memcmp(header.magic, "FTF1", 4) != 0 || header.glyphFirst != kGlyphFirst ||
        header.glyphCount != kGlyphCount || sizeof(header) + uint64_t(header.fontCount) * sizeof(FontEntry) > kSize) {
        return false;
    }
    const Glyph* tables[kFontClasses][2] = {};
    for (uint32_t i = 0; i < header.fontCount; ++i) {
        FontEntry entry;
        std::memcpy(&entry, kFontFile + sizeof(header) + i * sizeof(FontEntry), sizeof(entry));
        const int cls = static_cast<int>(entry.id / 10), index = scaleIndex(static_cast<int>(entry.id % 10));
        if (cls >= kFontClasses || index < 0 || (entry.glyphs & 3) != 0 ||
            uint64_t(entry.glyphs) + kGlyphCount * sizeof(Glyph) > kSize) {
            return false;
        }
        const auto* table = reinterpret_cast<const Glyph*>(kFontFile + entry.glyphs);
        for (int g = 0; g < kGlyphCount; ++g) {
            if (table[g].bitmap != 0 && uint64_t(table[g].bitmap) + uint64_t(table[g].w) * table[g].h > kSize) { return false; }
        }
        tables[cls][index] = table;
    }
    for (int cls = 0; cls < kFontClasses; ++cls) {
        if (tables[cls][0] == nullptr || tables[cls][1] == nullptr) { return false; }
    }
    std::memcpy(s_tables, tables, sizeof(tables));
    return true;
}

int capHeight(Font font, int scale) {
    const Glyph* table = tableOf(font, scale);
    return table != nullptr ? -glyph(table, 'H').yoff : 0;
}

int textWidth(Font font, int scale, const char* text) {
    const Glyph* table = tableOf(font, scale);
    return table != nullptr && text != nullptr ? width(table, text) : 0;
}

int drawText(Canvas& canvas, Font font, int scale, int x, int y, const char* text, Color color, int maxWidth) {
    const Glyph* table = tableOf(font, scale);
    if (table == nullptr || text == nullptr) { return x; }
    const bool clip = maxWidth > 0 && width(table, text) > maxWidth;
    const int limit = clip ? maxWidth - width(table, "...") : 0;
    int pen64 = x * 64;
    for (const char* c = text; *c != '\0'; ++c) {
        const Glyph& g = glyph(table, *c);
        if (clip && (pen64 + g.advance64) / 64 - x > limit) {
            const Glyph& dot = glyph(table, '.');
            for (int i = 0; i < 3; ++i, pen64 += dot.advance64) { drawGlyph(canvas, dot, pen64, y, color); }
            break;
        }
        drawGlyph(canvas, g, pen64, y, color);
        pen64 += g.advance64;
    }
    return (pen64 + 32) / 64;
}

}  // namespace warp::ui::assets
